sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    const interactionData = api.data.get_interaction_details_1?.modalDetails?.interactionDetails?.interaction;

    if (!interactionData) {
        console.error("Interaction data is not available");
        return;
    }

    let isNew = interactionData.isNew;
    const sysId = interactionData.sysId;
    const number = interactionData.number;
    const name = interactionData.targetDetails.name;

    if (!sysId) {
        console.error("Interaction sysId is required");
        return;
    }

    const emailCountQuery = `instanceSTARTSWITH${sysId}^typeINsend-ready,sent`;

    helpers.snHttp(`/api/now/table/sys_email?sysparm_query=${encodeURIComponent(emailCountQuery)}`, {
            method: "GET"
        })
        .then(response => {
            const emailCount = response?.response?.result.length;

            const updatePayload = {
                short_description: event.context.item.value.minimizedTitle
            };

            if (emailCount === 1) {
                const currentUserSysId = api.context?.session?.user?.sys_id;

                if (currentUserSysId) {
                    updatePayload.assigned_to = currentUserSysId;
                } else {
                    console.warn("Could not determine current user sys_id");
                }

                isNew = true;
            } else {
                isNew = false;
            }

            return helpers.snHttp('/api/now/table/interaction/' + sysId, {
                method: "PATCH",
                body: updatePayload
            });
        })
        .then(response => {
            if (isNew) {
                const tableName = 'interaction';
                const url = `/nav_to.do?uri=${tableName}.do?sys_id=${sysId}`;
                const displayName = name || 'recipient';
                const displayNumber = number || sysId;

                helpers.translate("Email sent to {0} and created a new email interaction. {1}", [
                    displayName,
                    `<a href="${url}" target="_blank">${displayNumber}</a>`
                ]).then(notifyMessage => {
                    api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                        items: [{
                            id: "email_notification_success",
                            status: "positive",
                            icon: "check-circle-outline",
                            content: {
                                type: "html",
                                value: "<span>" + notifyMessage + "</span>"
                            },
                            action: {
                                type: "dismiss"
                            }
                        }]
                    });
                });
            }
        })
        .catch(error => {
            console.error("Error in updating the interaction - ", error);
        });
}
